75	@RestController
76	@CrossOrigin(exposedHeaders = "errors, content-type")
77	@RequestMapping("/api")
78	public class OwnerRestControllerV1 implements OwnersApi {
79	
80	    /**
81	     * Basic syntactic check for an email address: a non-empty local part, an '@', and a domain with
82	     * at least one dot and a two-or-more letter top-level label. Case is ignored here; accepted
83	     * addresses are lower-cased before being stored.
84	     */
85	    private static final Pattern EMAIL_PATTERN =
86	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
87	
88	    /** An owner's postcode, when supplied, must be exactly four digits. */
89	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
90	
91	    /**
92	     * Disposable e-mail domains an owner may not sign up with. An email whose domain (the part after
93	     * the '@', compared case-insensitively) is on this blocklist is rejected with a 400.
94	     */
95	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
96	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
97	
98	    /**
99	     * Dedicated logger for audit side-effects. Emitting audit records on a well-known, separately
100	     * named logger keeps them addressable independently of the class's diagnostic logging.
101	     */
102	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
103	
104	    /**
105	     * Dedicated logger for the welcome notification enqueued on a successful create. Emitting it on a
106	     * well-known, separately named logger keeps the notification stream addressable independently of the
107	     * audit records and the class's diagnostic logging.
108	     */
109	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
110	
111	    /**
112	     * Monotonically increasing sequence number stamped onto each structured {@code OWNER_CREATED}
113	     * audit event. It is process-wide (static) so the ordering holds across every owner created,
114	     * regardless of which controller instance handles the request.
115	     */
116	    private static final AtomicLong AUDIT_EVENT_SEQ = new AtomicLong(0);
117	
118	    /** Serializes the immutable structured audit event to its canonical JSON representation. */
119	    private static final ObjectMapper AUDIT_MAPPER = JsonMapper.builder().build();
120	
121	    /**
122	     * Maximum number of owners a single city may contain. A create that would take the owner's city
123	     * to more than this many owners - i.e. the city already holds this many - is rejected with a 409.
124	     */
125	    private static final int CITY_OWNER_LIMIT = 50;
126	
127	    /**
128	     * Number of owners a city must already hold for a create response and owner read to flag that the
129	     * city is approaching capacity. When the city holds between this many and {@link #CITY_OWNER_LIMIT}
130	     * minus one owners (40-49), the owner's {@code capacityWarning} is {@code true}; the hard rejection
131	     * at {@link #CITY_OWNER_LIMIT} is unchanged.
132	     */
133	    private static final int CITY_CAPACITY_WARNING_THRESHOLD = 40;
134	
135	    /**
136	     * Maximum number of owners that may be registered on a single day. A create that would take the
137	     * number of owners sharing a {@code registrationDate} beyond this many - i.e. that many owners
138	     * have already been created that day - is rejected with a 429.
139	     */
140	    private static final int DAILY_OWNER_LIMIT = 100;
141	
142	    /**
143	     * Number of owners that must already have been created for a given day before the create
144	     * response flags a bulk sign-up. When more than this many owners already share a
145	     * {@code registrationDate}, the response's {@code bulkSignupWarning} is {@code true}.
146	     */
147	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
148	
149	    /**
150	     * Fixed list of public holidays. A registration date that lands on one of these dates is treated
151	     * like a weekend and rolled forward to the next non-holiday business day.
152	     */
153	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
154	        LocalDate.of(2026, 1, 1),
155	        LocalDate.of(2026, 1, 26),
156	        LocalDate.of(2026, 4, 25),
157	        LocalDate.of(2026, 12, 25),
158	        LocalDate.of(2026, 12, 28));
159	
160	    /**
161	     * Request header carrying the client-supplied idempotency key. When a create repeats with a key
162	     * already seen, the originally created owner is returned instead of creating a duplicate.
163	     */
164	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
165	
166	    private final ClinicService clinicService;
167	
168	    private final OwnerMapper ownerMapper;
169	
170	    private final PetMapper petMapper;
171	
172	    private final VisitMapper visitMapper;
173	
174	    private final HttpServletRequest request;
175	
176	    /**
177	     * Remembers the owner produced by each previously seen {@code Idempotency-Key}, so a repeated
178	     * create with an already-seen key returns the originally created owner rather than a duplicate.
179	     */
180	    private final Map<String, OwnerDto> idempotencyStore = new ConcurrentHashMap<>();
181	
182	    public OwnerRestControllerV1(ClinicService clinicService,
183	                                 OwnerMapper ownerMapper,
184	                                 PetMapper petMapper,
185	                                 VisitMapper visitMapper,
186	                                 HttpServletRequest request) {
187	        this.clinicService = clinicService;
188	        this.ownerMapper = ownerMapper;
189	        this.petMapper = petMapper;
190	        this.visitMapper = visitMapper;
191	        this.request = request;
192	    }
193	
194	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
195	    @Override
196	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
197	        Collection<Owner> owners;
198	        if (lastName != null) {
199	            owners = this.clinicService.findOwnerByLastName(lastName);
200	        } else {
201	            owners = this.clinicService.findAllOwners();
202	        }
203	        if (owners.isEmpty()) {
204	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
205	        }
206	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
207	    }
208	
209	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
210	    @Override
211	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
212	        Owner owner = this.clinicService.findOwnerById(ownerId);
213	        if (owner == null) {
214	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
215	        }
216	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
217	        ownerDto.setBulkSignupWarning(isBulkSignupDay(owner.getRegistrationDate()));
218	        ownerDto.setCapacityWarning(isApproachingCityCapacity(owner.getCity()));
219	        ownerDto.setRiskFlag(computeRiskFlag(owner));
220	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
221	    }
222	
223	    /**
224	     * Determines whether the supplied day currently holds more than {@link #BULK_SIGNUP_WARNING_THRESHOLD}
225	     * owners sharing that {@code registrationDate}, which flags an unusually high volume of same-day
226	     * owner sign-ups.
227	     *
228	     * @param registrationDate the day to inspect, or {@code null}
229	     * @return {@code true} when more than the threshold of owners are registered on that day
230	     */
231	    private boolean isBulkSignupDay(LocalDate registrationDate) {
232	        return registrationDate != null
233	            && countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
234	    }
235	
236	    /**
237	     * Determines whether the supplied city is approaching its per-city capacity, i.e. it currently
238	     * holds between {@link #CITY_CAPACITY_WARNING_THRESHOLD} and {@link #CITY_OWNER_LIMIT} minus one
239	     * owners (40-49). This flags a city nearing the hard limit of {@link #CITY_OWNER_LIMIT}; that hard
240	     * rejection is unchanged.
241	     *
242	     * @param city the city to inspect, or {@code null}
243	     * @return {@code true} when the city holds 40-49 owners
244	     */
245	    private boolean isApproachingCityCapacity(String city) {
246	        if (city == null) {
247	            return false;
248	        }
249	        long count = countOwnersInCity(city);
250	        return count >= CITY_CAPACITY_WARNING_THRESHOLD && count < CITY_OWNER_LIMIT;
251	    }
252	
253	    /**
254	     * Determines whether the supplied city is over its soft capacity, i.e. it currently holds at
255	     * least {@link #CITY_CAPACITY_WARNING_THRESHOLD} owners - the soft limit that sits below the hard
256	     * per-city limit of {@link #CITY_OWNER_LIMIT}. Unlike {@link #isApproachingCityCapacity}, which is
257	     * a window that closes once the city is full, this stays {@code true} all the way up to and
258	     * including the hard limit, so a city at capacity is still reported as over its soft capacity.
259	     *
260	     * @param city the city to inspect, or {@code null}
261	     * @return {@code true} when the city holds at least {@link #CITY_CAPACITY_WARNING_THRESHOLD} owners
262	     */
263	    private boolean isOverSoftCityCapacity(String city) {
264	        return city != null && countOwnersInCity(city) >= CITY_CAPACITY_WARNING_THRESHOLD;
265	    }
266	
267	    /**
268	     * Determines whether an owner's email address is disposable-adjacent, i.e. its domain (the part
269	     * after the '@', compared case-insensitively) is a subdomain of one of the {@link
270	     * #DISPOSABLE_EMAIL_DOMAINS} that are blocked outright at create time. An exact disposable domain
271	     * is rejected with a 400 when the owner is created, so it never survives on a stored owner; a
272	     * subdomain such as {@code mail.mailinator.com} is admitted but is close enough to a disposable
273	     * provider to be flagged for review.
274	     *
275	     * @param email the owner's normalized email address, or {@code null}/blank when none is on file
276	     * @return {@code true} when the email's domain is a subdomain of a known disposable domain
277	     */
278	    private boolean isDisposableAdjacentEmail(String email) {
279	        if (!StringUtils.hasText(email)) {
280	            return false;
281	        }
282	        int at = email.indexOf('@');
283	        if (at < 0) {
284	            return false;
285	        }
286	        String domain = email.substring(at + 1).toLowerCase();
287	        return DISPOSABLE_EMAIL_DOMAINS.stream().anyMatch(blocked -> domain.endsWith("." + blocked));
288	    }
289	
290	    /**
291	     * Computes the owner's {@code riskFlag}, the review signal derived on read. It is {@code true}
292	     * when any of these hold: the owner is a possible duplicate (see
293	     * {@link #findPossibleDuplicate(Owner)}), the owner's email domain is disposable-adjacent (see
294	     * {@link #isDisposableAdjacentEmail(String)}), or the owner's city is over its soft capacity (see
295	     * {@link #isOverSoftCityCapacity(String)}); otherwise {@code false}.
296	     *
297	     * @param owner the owner to inspect
298	     * @return {@code true} when any review signal trips, otherwise {@code false}
299	     */
300	    private boolean computeRiskFlag(Owner owner) {
301	        return Boolean.TRUE.equals(owner.getPossibleDuplicate())
302	            || isDisposableAdjacentEmail(owner.getEmail())
303	            || isOverSoftCityCapacity(owner.getCity());
304	    }
305	
306	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
307	    @Override
308	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
309	        String idempotencyKey = idempotencyKey();
310	        if (idempotencyKey != null) {
311	            OwnerDto existing = this.idempotencyStore.get(idempotencyKey);
312	            if (existing != null) {
313	                return new ResponseEntity<>(existing, HttpStatus.OK);
314	            }
315	        }
316	        Owner owner = buildOwnerToCreate(ownerFieldsDto);
317	        boolean bulkSignupWarning = enforceCreateLimits(owner) > BULK_SIGNUP_WARNING_THRESHOLD;
318	        finalizeOwnerForCreate(owner);
319	        this.clinicService.saveOwner(owner);
320	        ResponseEntity<OwnerDto> response = createdOwnerResponse(owner, bulkSignupWarning);
321	        if (idempotencyKey != null) {
322	            this.idempotencyStore.put(idempotencyKey, response.getBody());
323	        }
324	        return response;
325	    }
326	
327	    /**
328	     * Returns the client-supplied {@code Idempotency-Key} for the current request, or {@code null}
329	     * when the header is absent or blank.
330	     */
331	    private String idempotencyKey() {
332	        String key = this.request.getHeader(IDEMPOTENCY_KEY_HEADER);
333	        return StringUtils.hasText(key) ? key : null;
334	    }
335	
336	    /**
337	     * Resolves, validates and maps a create request into a fully-normalized {@link Owner} that is
338	     * ready to persist except for the derived fields assigned by {@link #finalizeOwnerForCreate}. The
339	     * submitted address is canonicalized, the required fields and the optional postcode and
340	     * registration date are validated, and the mapped owner's telephone and email are normalized. The
341	     * registration date is defaulted to the server date when absent and rolled forward to a business
342	     * day. The household id and identity key are derived; a create whose identity key matches an
343	     * existing, non-deleted owner is rejected with a 409 unless it opts in with {@code sharesHousehold},
344	     * and otherwise a soft-match duplicate is flagged.
345	     *
346	     * @param ownerFieldsDto the submitted owner fields
347	     * @return the normalized owner, not yet persisted
348	     */
349	    private Owner buildOwnerToCreate(OwnerFieldsDto ownerFieldsDto) {
350	        resolveAddressFields(ownerFieldsDto);
351	        validateRequiredFields(ownerFieldsDto);
352	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
353	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
354	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
355	        owner.setEmail(normalizeEmail(owner.getEmail()));
356	        validateRegistrationDate(owner.getRegistrationDate());
357	        if (owner.getRegistrationDate() == null) {
358	            owner.setRegistrationDate(LocalDate.now());
359	        }
360	        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
361	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
362	        resolveHouseholdIdentity(owner, sharesHousehold);
363	        return owner;
364	    }
365	
366	    /**
367	     * Places the owner about to be created into its household and settles its identity against the
368	     * owners already on file. The owner's {@code householdId} is still derived deterministically from
369	     * its last name and postcode (it drives the household size and membership-level cap), but identity
370	     * is now decided solely by the {@code identityKey}, the SHA-256 digest over the normalized
371	     * telephone, email and the last name's Soundex code. Unless the request opted into a shared
372	     * household, an owner whose identity key matches any existing, non-deleted owner is rejected with a
373	     * 409; and, again only when the household was not opted into, a soft-match against an existing owner
374	     * flags the new owner as a possible duplicate. Two owners sharing a last name and postcode but with
375	     * different telephones now derive different identity keys, so they are admitted (as a soft match)
376	     * rather than rejected, with their membership level later capped by
377	     * {@link #applyMembershipLevelCap(Owner)}.
378	     *
379	     * @param owner the normalized owner about to be created, with its contact details already normalized
380	     * @param sharesHousehold whether the request opted into joining an existing household
381	     */
382	    private void resolveHouseholdIdentity(Owner owner, boolean sharesHousehold) {
383	        owner.setHouseholdId(HouseholdNormalizer.householdId(owner.getLastName(), owner.getPostcode()));
384	        owner.setIdentityKey(buildIdentityKey(owner));
385	        if (!sharesHousehold) {
386	            rejectDuplicateIdentity(owner);
387	        }
388	        Integer possibleDuplicateOf = sharesHousehold ? null : findPossibleDuplicate(owner);
389	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
390	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
391	    }
392	
393	    /**
394	     * Enforces the per-city and per-day capacity limits for a new owner, in that order. A create that
395	     * would take the owner's city beyond {@link #CITY_OWNER_LIMIT} owners is rejected with a 409, and
396	     * one that would take the owner's registration date beyond {@link #DAILY_OWNER_LIMIT} owners is
397	     * rejected with a 429. The returned count is the number of owners already sharing the owner's
398	     * registration date, measured before it is saved, which the caller uses to decide the response's
399	     * {@code bulkSignupWarning}.
400	     *
401	     * @param owner the normalized owner about to be created
402	     * @return the number of owners already registered on the owner's registration date
403	     */
404	    private long enforceCreateLimits(Owner owner) {
405	        if (countOwnersInCity(owner.getCity()) >= CITY_OWNER_LIMIT) {
406	            throw new OwnerCityFullException(owner.getCity());
407	        }
408	        long ownersRegisteredOnDay = countOwnersRegisteredOn(owner.getRegistrationDate());
409	        if (ownersRegisteredOnDay >= DAILY_OWNER_LIMIT) {
410	            throw new OwnerDailyLimitException(owner.getRegistrationDate());
411	        }
412	        return ownersRegisteredOnDay;
413	    }
414	
415	    /**
416	     * Assigns the derived fields that only apply once the owner has cleared the create checks: its
417	     * de-duplicated member id, the number of existing namesakes, the household size once the
418	     * new owner is added, and the membership-level ceiling imposed by the household the owner joins.
419	     *
420	     * @param owner the normalized owner about to be created
421	     */
422	    private void finalizeOwnerForCreate(Owner owner) {
423	        owner.setMemberId(buildMemberId(owner));
424	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
425	        owner.setHouseholdSize(countHouseholdMembers(owner.getHouseholdId()) + 1);
426	        applyMembershipLevelCap(owner);
427	    }
428	
429	    /**
430	     * Caps the membership level of an owner about to be created so it cannot exceed one above the
431	     * current maximum membership level among the owner's existing household members. The owner is not
432	     * yet persisted, so {@link #activeHouseholdMembers(String)} returns exactly the members already on
433	     * file; each member's effective (already-capped) level is read via
434	     * {@link org.springframework.samples.petclinic.mapper.MembershipLevel#forOwner(Owner)}. When the
435	     * household has no existing member no ceiling applies and the cap is left unset, so the owner keeps
436	     * its fully-derived level.
437	     *
438	     * @param owner the normalized owner about to be created, with its {@code householdId} already set
439	     */
440	    private void applyMembershipLevelCap(Owner owner) {
441	        activeHouseholdMembers(owner.getHouseholdId()).stream()
442	            .mapToInt(org.springframework.samples.petclinic.mapper.MembershipLevel::forOwner)
443	            .max()
444	            .ifPresent(maxLevel -> owner.setMembershipLevelCap(maxLevel + 1));
445	    }
446	
447	    /**
448	     * Builds the {@code 201 Created} response for a freshly persisted owner: maps it to a DTO, emits
449	     * the audit record, sets the {@code bulkSignupWarning} the caller computed from the pre-save daily
450	     * count, and adds the {@code Location} header pointing at the new owner.
451	     *
452	     * @param owner the owner that has just been saved, with its generated id populated
453	     * @param bulkSignupWarning whether the response should flag an unusually high same-day sign-up volume
454	     * @return the created-owner response
455	     */
456	    private ResponseEntity<OwnerDto> createdOwnerResponse(Owner owner, boolean bulkSignupWarning) {
457	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
458	        logOwnerCreated(owner, ownerDto);
459	        emitOwnerCreatedEvent(owner, ownerDto);
460	        enqueueWelcomeNotification(owner);
461	        ownerDto.setBulkSignupWarning(bulkSignupWarning);
462	        ownerDto.setCapacityWarning(isApproachingCityCapacity(owner.getCity()));
463	        ownerDto.setRiskFlag(computeRiskFlag(owner));
464	        HttpHeaders headers = new HttpHeaders();
465	        headers.setLocation(UriComponentsBuilder.newInstance()
466	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
467	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
468	    }
469	
470	    /**
471	     * Emits the human-readable {@code OWNER_CREATED} audit line on the {@code AUDIT} logger, alongside
472	     * the structured event written by {@link #emitOwnerCreatedEvent}. The line records the owner's id,
473	     * member id, registration date and membership level. Kept as its own method so the response-builder
474	     * stays focused on assembling the response and the single audit-line format lives in one place.
475	     *
476	     * @param owner the owner that has just been saved, with its generated id populated
477	     * @param ownerDto the mapped DTO, source of the derived membership level
478	     */
479	    private void logOwnerCreated(Owner owner, OwnerDto ownerDto) {
480	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
481	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
482	            ownerDto.getMembershipLevel());
483	    }
484	
485	    /**
486	     * Emits the immutable, structured {@code OWNER_CREATED} audit event on the {@code AUDIT} logger,
487	     * alongside the human-readable audit line. The event is a JSON object
488	     * {@code {seq, ownerId, memberId, membershipLevel, event}} where {@code seq} is a
489	     * process-wide, monotonically increasing sequence across all creates. Its {@code memberId}
490	     * field carries the owner's primary identifier as returned by {@link #primaryIdentifier(Owner)}.
491	     *
492	     * @param owner the owner that has just been saved, with its generated id populated
493	     * @param ownerDto the mapped DTO, source of the derived membership level
494	     */
495	    private void emitOwnerCreatedEvent(Owner owner, OwnerDto ownerDto) {
496	        OwnerCreatedEvent event = new OwnerCreatedEvent(AUDIT_EVENT_SEQ.incrementAndGet(),
497	            owner.getId(), primaryIdentifier(owner), ownerDto.getMembershipLevel(), "OWNER_CREATED");
498	        try {
499	            AUDIT.info(AUDIT_MAPPER.writeValueAsString(event));
500	        }
501	        catch (JacksonException e) {
502	            AUDIT.warn("failed to serialize OWNER_CREATED audit event for owner id={}", owner.getId(), e);
503	        }
504	    }
505	
506	    /**
507	     * Enqueues the welcome notification for a freshly created owner by emitting a line on the
508	     * {@code NOTIFY} logger that carries the owner's id and member id. Kept as its own method, alongside
509	     * the audit emitters, so the response-builder stays focused on assembling the response and the
510	     * notification format lives in one place.
511	     *
512	     * @param owner the owner that has just been saved, with its generated id populated
513	     */
514	    private void enqueueWelcomeNotification(Owner owner) {
515	        NOTIFY.info("welcome notification enqueued for owner id={} memberId={}",
516	            owner.getId(), owner.getMemberId());
517	    }
518	
519	    /**
520	     * Returns the owner's primary identifier - the value the structured audit event carries as its
521	     * {@code memberId}. This is the owner's unified member id.
522	     *
523	     * @param owner the owner whose primary identifier is required
524	     * @return the owner's current primary identifier
525	     */
526	    private String primaryIdentifier(Owner owner) {
527	        return owner.getMemberId();
528	    }
529	
530	    /**
531	     * Immutable structured payload of an {@code OWNER_CREATED} audit event. The {@code memberId}
532	     * field holds the owner's primary identifier (see {@link #primaryIdentifier(Owner)}).
533	     */
534	    private record OwnerCreatedEvent(long seq, Integer ownerId, String memberId,
535	        Integer membershipLevel, String event) {
536	    }
537	
538	    /**
539	     * Canonicalizes the submitted address fields into the form that is validated, stored and
540	     * returned, before any required-field check or mapping runs. This is the single place a create
541	     * request's address input is resolved.
542	     *
543	     * <p>The structured fields are preferred over the flat input for backward compatibility: when a
544	     * non-blank {@code addressLine1} is supplied, {@code addressLine1} and the optional
545	     * {@code addressLine2} are {@link AddressNormalizer#normalize normalized} in place and the flat
546	     * {@code address} is set to the composed value - the normalized {@code addressLine1}, with a
547	     * single space and the normalized {@code addressLine2} appended when {@code addressLine2} is
548	     * present. When no structured line is supplied the flat {@code address} is normalized in place,
549	     * exactly as before. Either way everything downstream - the required-field check, the mapping onto
550	     * {@link Owner} and the response - sees the canonical address rather than the raw input. A value
551	     * that is blank only after normalization is left blank here and rejected later by
552	     * {@link #validateRequiredFields}.
553	     *
554	     * @param ownerFieldsDto the submitted owner fields, mutated in place with the resolved address
555	     */
556	    private void resolveAddressFields(OwnerFieldsDto ownerFieldsDto) {
557	        String line1 = AddressNormalizer.normalize(ownerFieldsDto.getAddressLine1());
558	        String line2 = AddressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
559	        if (!line1.isEmpty()) {
560	            ownerFieldsDto.setAddressLine1(line1);
561	            ownerFieldsDto.setAddressLine2(line2.isEmpty() ? null : line2);
562	            ownerFieldsDto.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
563	        }
564	        else {
565	            ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
566	        }
567	    }
568	
569	    /**
570	     * Rejects an owner payload that is missing or blank in any required field. Collects the name of
571	     * every offending field and, if there is at least one, raises a {@link MissingOwnerFieldsException}
572	     * so the client receives a 400 whose {@code errors} array lists each missing field. The address is
573	     * checked in its resolved form (see {@link #resolveAddressFields}), which is satisfied by either a
574	     * non-blank {@code addressLine1} or the flat {@code address}, so a value that is blank only after
575	     * normalization is still rejected.
576	     *
577	     * @param ownerFieldsDto the submitted owner fields
578	     */
579	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
580	        List<String> missingFields = new ArrayList<>();
581	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
582	            missingFields.add("firstName");
583	        }
584	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
585	            missingFields.add("lastName");
586	        }
587	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
588	            missingFields.add("address");
589	        }
590	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
591	            missingFields.add("city");
592	        }
593	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
594	            missingFields.add("telephone");
595	        }
596	        if (!missingFields.isEmpty()) {
597	            throw new MissingOwnerFieldsException(missingFields);
598	        }
599	    }
600	
601	    /**
602	     * Validates an owner's optional postcode. Postcode is optional, so a missing or blank value is
603	     * accepted unchanged. When a value is supplied it must be exactly four digits; and when the owner's
604	     * city maps to a known region the postcode must fall within that region's inclusive range (checked
605	     * via {@link OwnerLocality#postcodeMatchesCity}, which owns the region table). A city with no known
606	     * region accepts any 4-digit postcode. A malformed or out-of-range postcode is rejected with a 400
607	     * whose {@code errors} array lists {@code postcode}.
608	     *
609	     * @param postcode the submitted postcode, or {@code null} when none was supplied
610	     * @param city the owner's city, whose region determines the acceptable postcode range
611	     * @throws InvalidOwnerFieldsException if a supplied postcode is not four digits or is out of range
612	     */
613	    private void validatePostcode(String postcode, String city) {
614	        if (!StringUtils.hasText(postcode)) {
615	            return;
616	        }
617	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
618	            throw new InvalidOwnerFieldsException(List.of("postcode"));
619	        }
620	        if (!OwnerLocality.postcodeMatchesCity(postcode, city)) {
621	            throw new InvalidOwnerFieldsException(List.of("postcode"));
622	        }
623	    }
624	
625	    /**
626	     * Validates an owner's optional registration date. Registration date is optional, so a missing
627	     * value is accepted (the create later defaults it to the server date). When a value is supplied
628	     * it may not lie in the future: a date later than the server's current date is rejected with a
629	     * 400 whose {@code errors} array lists {@code registrationDate}.
630	     *
631	     * @param registrationDate the submitted registration date, or {@code null} when none was supplied
632	     * @throws InvalidOwnerFieldsException if a supplied date is later than the server date
633	     */
634	    private void validateRegistrationDate(LocalDate registrationDate) {
635	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
636	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
637	        }
638	    }
639	
640	    /**
641	     * Rejects a submitted owner whose derived {@code identityKey} matches that of any existing,
642	     * non-deleted owner - the same normalized telephone, email and last-name Soundex, which marks the
643	     * same person being entered twice. This single identity key is the whole of duplicate detection:
644	     * because the telephone is part of the key, distinct people who merely share a last name and
645	     * postcode (but differ in telephone) derive a different key and so are admitted rather than
646	     * rejected. Soft-deleted owners are ignored, and the email-domain blocklist has already been
647	     * applied when the email was normalized. A genuine identity collision is reported to the client as
648	     * a 409 Conflict. A request may knowingly bypass this check by opting in with
649	     * {@code sharesHousehold}, in which case it is not performed.
650	     *
651	     * @param owner the normalized owner about to be created, with its {@code identityKey} already set
652	     */
653	    private void rejectDuplicateIdentity(Owner owner) {
654	        boolean identityInUse = this.clinicService.findAllOwners().stream()
655	            .filter(existing -> !existing.isDeleted())
656	            .anyMatch(existing -> owner.getIdentityKey().equals(existing.getIdentityKey()));
657	        if (identityInUse) {
658	            throw new DuplicateOwnerIdentityException(owner.getIdentityKey());
659	        }
660	    }
661	
662	    /**
663	     * Returns the owners that currently belong to the household identified by {@code householdId} -
664	     * those sharing that derived id that have not been soft-deleted. Soft-deleted owners are excluded
665	     * because they no longer count as present members, so this is the household as it stands for the
666	     * owner being created. This is the single lookup of a household's current members behind the
667	     * household checks that reason about who is already there.
668	     *
669	     * @param householdId the derived household identifier to look up
670	     * @return the existing, non-deleted owners sharing that household, in no particular order
671	     */
672	    private List<Owner> activeHouseholdMembers(String householdId) {
673	        return this.clinicService.findAllOwners().stream()
674	            .filter(existing -> !existing.isDeleted())
675	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
676	            .collect(Collectors.toList());
677	    }
678	
679	    /**
680	     * Derives the owner's {@code identityKey} as the SHA-256 hex digest over
681	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}, where the telephone
682	     * and email have already been normalized (the email lower-cased, or the empty string when none was
683	     * supplied) and the last name is reduced to its {@link Soundex} code. Because the normalized
684	     * telephone is part of the key, two owners who differ only in telephone derive different identity
685	     * keys, so they are not the same identity even when they share a household.
686	     *
687	     * @param owner the normalized owner about to be created, with its contact details already normalized
688	     * @return the derived identity key, as 64 lower-case hex characters
689	     */
690	    private String buildIdentityKey(Owner owner) {
691	        String email = StringUtils.hasText(owner.getEmail()) ? owner.getEmail() : "";
692	        return Sha256.hex(owner.getTelephone() + "|" + email + "|" + Soundex.encode(owner.getLastName()));
693	    }
694	
695	    /**
696	     * Detects a soft-match duplicate for the owner about to be created. A soft match is an owner whose
697	     * derived {@code identityKey} differs from an existing owner's - so it is not the same identity, and
698	     * not a 409 - yet shares that owner's last-name {@link Soundex} code and {@code postcode}. Such an
699	     * owner is still created, but is flagged as a possible duplicate of the matching owner. In
700	     * particular, two owners with the same last name and postcode but different telephones now derive
701	     * different identity keys, so instead of the old hard household-duplicate rejection they surface
702	     * here as a soft match. This is only consulted for owners that did not opt into a shared household:
703	     * an owner that declares {@code sharesHousehold} is a known household member, not a suspected
704	     * duplicate, so it is never flagged. The comparison only applies when a postcode was supplied, since
705	     * both owners must share one; when several existing owners match, the earliest (lowest id) is used.
706	     *
707	     * @param owner the normalized owner about to be created, with its {@code identityKey} already set
708	     * @return the id of the matching existing owner, or {@code null} when there is no soft match
709	     */
710	    private Integer findPossibleDuplicate(Owner owner) {
711	        if (!StringUtils.hasText(owner.getPostcode())) {
712	            return null;
713	        }
714	        String soundex = Soundex.encode(owner.getLastName());
715	        return this.clinicService.findAllOwners().stream()
716	            .filter(existing -> !existing.isDeleted())
717	            .filter(existing -> !owner.getIdentityKey().equals(existing.getIdentityKey()))
718	            .filter(existing -> soundex.equals(Soundex.encode(existing.getLastName())))
719	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
720	            .map(Owner::getId)
721	            .filter(id -> id != null)
722	            .min(Integer::compareTo)
723	            .orElse(null);
724	    }
725	
726	    /**
727	     * Normalizes an optional email address for owner creation. Email is optional, so a missing or
728	     * blank value is left untouched. When a value is supplied it must be a syntactically valid
729	     * address; the accepted value is lower-cased before it is stored and returned.
730	     *
731	     * @param email the raw email value submitted by the client, or {@code null}
732	     * @return the lower-cased email, or the original blank/{@code null} value when none was supplied
733	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address
734	     */
735	    private String normalizeEmail(String email) {
736	        if (!StringUtils.hasText(email)) {
737	            return email;
738	        }
739	        if (!EMAIL_PATTERN.matcher(email).matches()) {
740	            throw new InvalidOwnerFieldsException(List.of("email"));
741	        }
742	        String normalized = email.toLowerCase();
743	        String domain = normalized.substring(normalized.indexOf('@') + 1);
744	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
745	            throw new InvalidOwnerFieldsException(List.of("email"));
746	        }
747	        return normalized;
748	    }
749	
750	    /**
751	     * Assigns the owner's member id, formatted {@code <REGION><FY><HASH8><CHK>}. The region is derived
752	     * from the owner's postcode (falling back to its city), FY is the two-digit fiscal year of the
753	     * (business-day-adjusted) registration date, and the id itself - region, fiscal year, the hash of
754	     * the owner's normalized telephone and last name, and the trailing Luhn check digit - is composed
755	     * by {@link MemberId}. When the composed id collides with an existing owner's member id, it is
756	     * de-duplicated by appending {@code -<n>} with the smallest {@code n} of two or more that makes it
757	     * unique.
758	     *
759	     * @param owner the normalized owner about to be created
760	     * @return the assigned, de-duplicated member id
761	     */
762	    private String buildMemberId(Owner owner) {
763	        String region = OwnerLocality.forPostcodeAndCity(owner.getPostcode(), owner.getCity());
764	        int fiscalYear = FiscalYear.twoDigit(owner.getRegistrationDate());
765	        String id = MemberId.forRegionYearAndIdentity(region, fiscalYear, owner.getTelephone(), owner.getLastName());
766	        return deduplicateMemberId(id);
767	    }
768	
769	    /**
770	     * De-duplicates a freshly composed member id against the ids of all existing owners. When the id is
771	     * already unique it is returned unchanged; otherwise {@code -<n>} is appended, using the smallest
772	     * {@code n} of two or more that yields an id no existing owner holds.
773	     *
774	     * @param id the composed member id, before de-duplication
775	     * @return the same id when unique, otherwise the id with the smallest available {@code -<n>} suffix
776	     */
777	    private String deduplicateMemberId(String id) {
778	        Set<String> existingIds = this.clinicService.findAllOwners().stream()
779	            .map(Owner::getMemberId)
780	            .filter(existing -> existing != null)
781	            .collect(Collectors.toSet());
782	        if (!existingIds.contains(id)) {
783	            return id;
784	        }
785	        int suffix = 2;
786	        while (existingIds.contains(id + "-" + suffix)) {
787	            suffix++;
788	        }
789	        return id + "-" + suffix;
790	    }
791	
792	    /**
793	     * Counts how many owners already exist that share the supplied first and last name, compared
794	     * case-insensitively. This reflects the number of namesakes present <em>before</em> the current
795	     * owner is created and is stored on the new owner as its {@code namesakeCount}.
796	     *
797	     * @param firstName the submitted owner's first name
798	     * @param lastName the submitted owner's last name
799	     * @return the number of existing owners with the same first and last name, ignoring case
800	     */
801	    private int countNamesakes(String firstName, String lastName) {
802	        return (int) this.clinicService.findAllOwners().stream()
803	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
804	                && lastName.equalsIgnoreCase(existing.getLastName()))
805	            .count();
806	    }
807	
808	    /**
809	     * Counts how many existing owners already belong to the supplied household, identified by its
810	     * {@code householdId}. Used when creating an owner to determine the household's size once the new
811	     * owner is added (this count plus one).
812	     *
813	     * @param householdId the normalized household identifier of the owner being created
814	     * @return the number of existing owners already sharing that {@code householdId}
815	     */
816	    private int countHouseholdMembers(String householdId) {
817	        return (int) this.clinicService.findAllOwners().stream()
818	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
819	            .count();
820	    }
821	
822	    /**
823	     * Counts how many owners already live in the supplied city, compared case-insensitively. Used to
824	     * enforce the per-city capacity limit when a new owner is created.
825	     *
826	     * @param city the submitted owner's city
827	     * @return the number of existing owners in that city, ignoring case
828	     */
829	    private long countOwnersInCity(String city) {
830	        return this.clinicService.findAllOwners().stream()
831	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
832	            .count();
833	    }
834	
835	    /**
836	     * Counts how many owners have already been created on the supplied registration date. Used to
837	     * enforce the per-day capacity limit when a new owner is created.
838	     *
839	     * @param registrationDate the registration date of the owner being created
840	     * @return the number of existing owners already registered on that date
841	     */
842	    /**
843	     * Rolls a registration date forward to a business day. A registration date must fall on a
844	     * business day, so when the supplied or defaulted date lands on a Saturday, Sunday or a listed
845	     * public holiday it is moved forward to the next non-holiday weekday; a plain weekday is
846	     * returned unchanged. Every value derived from the registration date (such as the member id's
847	     * fiscal-year segment) and the daily create-limit therefore use the adjusted date.
848	     *
849	     * @param date the effective registration date, whether supplied or defaulted to the server date
850	     * @return the same date when it is a business day, otherwise the next non-holiday weekday
851	     */
852	    private LocalDate toBusinessDay(LocalDate date) {
853	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
854	            date = date.plusDays(1);
855	        }
856	        return date;
857	    }
858	
859	    private boolean isWeekend(LocalDate date) {
860	        return date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY;
861	    }
862	
863	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
864	        return this.clinicService.findAllOwners().stream()
865	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
866	            .count();
867	    }
868	
869	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
870	    @Override
871	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
872	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
873	        if (currentOwner == null) {
874	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
875	        }
876	        currentOwner.setAddress(ownerFieldsDto.getAddress());
877	        currentOwner.setCity(ownerFieldsDto.getCity());
878	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
879	        currentOwner.setLastName(ownerFieldsDto.getLastName());
880	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
881	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
882	        this.clinicService.saveOwner(currentOwner);
883	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
884	    }
885	
886	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
887	    @Transactional
888	    @Override
889	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
890	        Owner owner = this.clinicService.findOwnerById(ownerId);
891	        if (owner == null) {
892	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
893	        }
894	        owner.setDeleted(true);
895	        this.clinicService.saveOwner(owner);
896	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
897	    }
898	
899	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
900	    @Override
901	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
902	        Owner owner = this.clinicService.findOwnerById(ownerId);
903	        if (owner == null) {
904	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
905	        }
906	        HttpHeaders headers = new HttpHeaders();
907	        Pet pet = petMapper.toPet(petFieldsDto);
908	        owner.setId(ownerId);
909	        pet.setOwner(owner);
910	        pet.getType().setName(null);
911	        this.clinicService.savePet(pet);
912	        PetDto petDto = petMapper.toPetDto(pet);
913	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
914	            .buildAndExpand(pet.getId()).toUri());
915	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
916	    }
917	
918	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
919	    @Override
920	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
921	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
922	        if (currentOwner != null) {
923	            Pet currentPet = this.clinicService.findPetById(petId);
924	            if (currentPet != null) {
925	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
926	                currentPet.setName(petFieldsDto.getName());
927	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
928	                this.clinicService.savePet(currentPet);
929	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
930	            }
931	        }
932	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
933	    }
