935	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
936	    @Override
937	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
938	        HttpHeaders headers = new HttpHeaders();
939	        Visit visit = visitMapper.toVisit(visitFieldsDto);
940	        Pet pet = new Pet();
941	        pet.setId(petId);
942	        visit.setPet(pet);
943	        this.clinicService.saveVisit(visit);
944	        VisitDto visitDto = visitMapper.toVisitDto(visit);
945	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
946	            .buildAndExpand(visit.getId()).toUri());
947	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
948	    }
