950	
951	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
952	    @Override
953	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
954	        Owner owner = this.clinicService.findOwnerById(ownerId);
955	        if (owner != null) {
956	            Pet pet = owner.getPet(petId);
957	            if (pet != null) {
958	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
959	            }
960	        }
961	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
962	    }
